@@ -0,0 +1,47 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include <cstdlib>
+#include <iostream>
+
+#include <KConfigGroup>
+#include <KSharedConfig>
+
+using namespace Qt::StringLiterals;
+
+/**
+ * Move the panel views configuration from [PlasmaViews][Panel N] to
+ * [PlasmaViews][<shell>][Panel N], so that panels of different shell
+ * packages that happen to have the same id don't share their settings.
+ *
+ * @since 6.9
+ */
+int main()
+{
+    const KSharedConfigPtr configPtr = KSharedConfig::openConfig(QStringLiteral("plasmashellrc"), KConfig::FullConfig);
+    KConfigGroup views(configPtr, QStringLiteral("PlasmaViews"));
+    if (!views.exists() || views.groupList().empty()) {
+        std::cout << "plasmashellrc doesn't have any PlasmaViews. No need to update config." << std::endl;
+        return EXIT_SUCCESS;
+    }
+
+    const QStringList groupList = views.groupList();
+    for (const QString &name : groupList) {
+        if (!name.startsWith(QLatin1String("Panel "))) {
+            continue;
+        }
+
+        KConfigGroup oldGroup(&views, name);
+        // Panels saved before the shell was written to their config are most likely Plasma Desktop ones
+        const QString shell = oldGroup.readEntry("shell", u"org.kde.plasma.desktop"_s);
+        KConfigGroup newGroup = views.group(shell).group(name);
+        oldGroup.copyTo(&newGroup);
+        newGroup.deleteEntry("shell");
+        views.deleteGroup(name);
+    }
+
+    return configPtr->sync() ? EXIT_SUCCESS : EXIT_FAILURE;
+}
